  FIELD ROW07  AT 8,1  LEN 76 PROT COLOR=GREEN
  FIELD ROW08  AT 9,1  LEN 76 PROT COLOR=GREEN
  FIELD ROW09  AT 10,1 LEN 76 PROT COLOR=GREEN
  FIELD ROW10  AT 11,1 LEN 76 PROT COLOR=GREEN
  FIELD ROW11  AT 12,1 LEN 76 PROT COLOR=GREEN
  FIELD ROW12  AT 13,1 LEN 76 PROT COLOR=GREEN
