  FIELD ROW21  AT 22,1 LEN 76 PROT COLOR=GREEN
  FIELD ROW22  AT 23,1 LEN 76 PROT COLOR=GREEN
  FIELD ROW23  AT 24,1 LEN 76 PROT COLOR=GREEN
  FIELD ROW24  AT 25,1 LEN 76 PROT COLOR=GREEN
  FIELD ROW25  AT 26,1 LEN 76 PROT COLOR=GREEN
  FIELD ROW26  AT 27,1 LEN 76 PROT COLOR=GREEN
  FIELD ROW27  AT 28,1 LEN 76 PROT COLOR=GREEN
  FIELD ROW28  AT 29,1 LEN 76 PROT COLOR=GREEN
