  FIELD PROMPT AT 40,1 LEN 3  PROT BRIGHT COLOR=GREEN     "==>"
  INPUT INPUT  AT 40,12 LEN 63 UNDERSCORE COLOR=WHITE
  STOP         AT 40,75
  FIELD FOOTER AT 42,1 LEN 36 PROT COLOR=BLUE             "F3=exit  Enter=send"
  CURSOR AT INPUT
ENDMAP
